        }
    }
    roleList = authorizer.listAllRoles();
    assertEquals(5, roleList.size());
    for (int i = 0; i < roleCnt; i++) {
        if (i % 2 == 1)
            assertEquals("newRole" + i, roleList.get(i / 2));
    }
}

