    roleNames.sort(null);
    for (int i = 0; i < roleNames.size(); i++) {
        assertEquals(roles[i].name, roleNames.get(i));
    }
}

@Test
public void test() throws AuthException {
    Role[] roles = new Role[5];
    for (int i = 0; i < roles.length; i++) {
        roles[i] = new Role("role" + i);
        for (int j = 0; j <= i; j++) {
            PathPrivilege pathPrivilege = new PathPrivilege("root.a.b.c" + j);
            pathPrivilege.privileges.add(j);
            roles[i].privilegeList.add(pathPrivilege);
        }
    }
    // create
    Role role = manager.getRole(roles[0].name);
    assertEquals(null, role);
    for (Role role1 : roles) assertEquals(true, manager.createRole(role1.name));
    for (Role role1 : roles) {
        role = manager.getRole(role1.name);
        assertEquals(role1.name, role.name);
    }
    assertEquals(false, manager.createRole(roles[0].name));
    boolean caught = false;
    try {
        manager.createRole("too");
    } catch (AuthException e) {
        caught = true;
    }
    assertEquals(true, caught);
    // delete
    assertEquals(false, manager.deleteRole("not a role"));
    assertEquals(true, manager.deleteRole(roles[roles.length - 1].name));
    assertEquals(null, manager.getRole(roles[roles.length - 1].name));
    assertEquals(false, manager.deleteRole(roles[roles.length - 1].name));
    // grant privilege
    role = manager.getRole(roles[0].name);
    String path = "root.a.b.c";
    int privilegeId = 0;
    assertEquals(false, role.hasPrivilege(path, privilegeId));
    assertEquals(true, manager.grantPrivilegeToRole(role.name, path, privilegeId));
    assertEquals(true, manager.grantPrivilegeToRole(role.name, path, privilegeId + 1));
    assertEquals(false, manager.grantPrivilegeToRole(role.name, path, privilegeId));
    role = manager.getRole(roles[0].name);
    assertEquals(true, role.hasPrivilege(path, privilegeId));
    caught = false;
    try {
        manager.grantPrivilegeToRole("not a role", path, privilegeId);
    } catch (AuthException e) {
        caught = true;
    }
    assertEquals(true, caught);
    caught = false;
    try {
        manager.grantPrivilegeToRole(role.name, path, -1);
    } catch (AuthException e) {
        caught = true;
    }
    assertEquals(true, caught);
    // revoke privilege
    role = manager.getRole(roles[0].name);
    assertEquals(true, manager.revokePrivilegeFromRole(role.name, path, privilegeId));
    assertEquals(false, manager.revokePrivilegeFromRole(role.name, path, privilegeId));
    caught = false;
    try {
        manager.revokePrivilegeFromRole("not a role", path, privilegeId);
    } catch (AuthException e) {
        caught = true;
    }
    assertEquals(true, caught);
    caught = false;
    try {
        manager.revokePrivilegeFromRole(role.name, path, -1);
    } catch (AuthException e) {
        caught = true;
    }
    assertEquals(true, caught);
    // list roles
    List<String> rolenames = manager.listAllRoles();
    rolenames.sort(null);
    for (int i = 0; i < roles.length - 1; i++) {
        assertEquals(roles[i].name, rolenames.get(i));
    }
}

@Test
public void test() throws IOException {
    User[] users = new User[5];
    for (int i = 0; i < users.length; i++) {
        users[i] = new User("user" + i, "password" + i);
        for (int j = 0; j <= i; j++) {
            PathPrivilege pathPrivilege = new PathPrivilege("root.a.b.c" + j);
            pathPrivilege.privileges.add(j);
            users[i].privilegeList.add(pathPrivilege);
            users[i].roleList.add("role" + j);
        }
    }
    // save
    for (User user : users) {
        try {
            accessor.saveUser(user);
        } catch (IOException e) {
            fail(e.getMessage());
        }
    }
    // load
    for (User user : users) {
        try {
            User loadedUser = accessor.loadUser(user.name);
            assertEquals(user, loadedUser);
        } catch (IOException e) {
            fail(e.getMessage());
        }
    }
    assertEquals(null, accessor.loadUser("not a user"));
    // list
    List<String> usernames = accessor.listAllUsers();
    usernames.sort(null);
    for (int i = 0; i < users.length; i++) {
        assertEquals(users[i].name, usernames.get(i));
    }
    // delete
    assertEquals(false, accessor.deleteUser("not a user"));
    assertEquals(true, accessor.deleteUser(users[users.length - 1].name));
    usernames = accessor.listAllUsers();
    assertEquals(users.length - 1, usernames.size());
    usernames.sort(null);
    for (int i = 0; i < users.length - 1; i++) {
        assertEquals(users[i].name, usernames.get(i));
    }
    User nullUser = accessor.loadUser(users[users.length - 1].name);
    assertEquals(null, nullUser);
}

@Test
public void test() throws AuthException {
    User[] users = new User[5];
    for (int i = 0; i < users.length; i++) {
        users[i] = new User("user" + i, "password" + i);
        for (int j = 0; j <= i; j++) {
            PathPrivilege pathPrivilege = new PathPrivilege("root.a.b.c" + j);
            pathPrivilege.privileges.add(j);
            users[i].privilegeList.add(pathPrivilege);
            users[i].roleList.add("role" + j);
        }
    }
    // create
    User user = manager.getUser(users[0].name);
    assertEquals(null, user);
    for (User user1 : users) assertEquals(true, manager.createUser(user1.name, user1.password));
    for (User user1 : users) {
        user = manager.getUser(user1.name);
        assertEquals(user1.name, user.name);
        assertEquals(AuthUtils.encryptPassword(user1.password), user.password);
    }
    assertEquals(false, manager.createUser(users[0].name, users[0].password));
    boolean caught = false;
    try {
        manager.createUser("too", "short");
    } catch (AuthException e) {
        caught = true;
    }
    assertEquals(true, caught);
    caught = false;
    try {
        manager.createUser("short", "too");
    } catch (AuthException e) {
        caught = true;
    }
    assertEquals(true, caught);
    // delete
    assertEquals(false, manager.deleteUser("not a user"));
    assertEquals(true, manager.deleteUser(users[users.length - 1].name));
    assertEquals(null, manager.getUser(users[users.length - 1].name));
    assertEquals(false, manager.deleteUser(users[users.length - 1].name));
    // grant privilege
    user = manager.getUser(users[0].name);
    String path = "root.a.b.c";
    int privilegeId = 0;
    assertEquals(false, user.hasPrivilege(path, privilegeId));
    assertEquals(true, manager.grantPrivilegeToUser(user.name, path, privilegeId));
    assertEquals(true, manager.grantPrivilegeToUser(user.name, path, privilegeId + 1));
    assertEquals(false, manager.grantPrivilegeToUser(user.name, path, privilegeId));
    user = manager.getUser(users[0].name);
    assertEquals(true, user.hasPrivilege(path, privilegeId));
    caught = false;
    try {
        manager.grantPrivilegeToUser("not a user", path, privilegeId);
    } catch (AuthException e) {
        caught = true;
    }
    assertEquals(true, caught);
    caught = false;
    try {
        manager.grantPrivilegeToUser(user.name, path, -1);
    } catch (AuthException e) {
        caught = true;
    }
    assertEquals(true, caught);
    // revoke privilege
    user = manager.getUser(users[0].name);
    assertEquals(true, manager.revokePrivilegeFromUser(user.name, path, privilegeId));
    assertEquals(false, manager.revokePrivilegeFromUser(user.name, path, privilegeId));
    caught = false;
    try {
        manager.revokePrivilegeFromUser("not a user", path, privilegeId);
    } catch (AuthException e) {
        caught = true;
    }
    assertEquals(true, caught);
    caught = false;
    try {
        manager.revokePrivilegeFromUser(user.name, path, -1);
    } catch (AuthException e) {
        caught = true;
    }
    assertEquals(true, caught);
    // update password
    String newPassword = "newPassword";
    String illegalPW = "new";
    assertEquals(true, manager.updateUserPassword(user.name, newPassword));
    assertEquals(false, manager.updateUserPassword(user.name, illegalPW));
    user = manager.getUser(user.name);
    assertEquals(AuthUtils.encryptPassword(newPassword), user.password);
    caught = false;
    try {
        manager.updateUserPassword("not a user", newPassword);
    } catch (AuthException e) {
        caught = true;
    }
    assertEquals(true, caught);
    // grant role
    String roleName = "newrole";
    assertEquals(true, manager.grantRoleToUser(roleName, user.name));
    assertEquals(false, manager.grantRoleToUser(roleName, user.name));
    user = manager.getUser(user.name);
    assertEquals(true, user.hasRole(roleName));
    caught = false;
    try {
        manager.grantRoleToUser("not a user", roleName);
    } catch (AuthException e) {
        caught = true;
    }
    assertEquals(true, caught);
    // revoke role
    assertEquals(true, manager.revokeRoleFromUser(roleName, user.name));
    assertEquals(false, manager.revokeRoleFromUser(roleName, user.name));
    user = manager.getUser(user.name);
    assertEquals(false, user.hasRole(roleName));
    caught = false;
    try {
        manager.revokeRoleFromUser("not a user", roleName);
    } catch (AuthException e) {
        caught = true;
    }
    assertEquals(true, caught);
    // list users
    List<String> usernames = manager.listAllUsers();
    usernames.sort(null);
    assertEquals(TsFileDBConstant.ADMIN_NAME, usernames.get(0));
    for (int i = 0; i < users.length - 1; i++) {
        assertEquals(users[i].name, usernames.get(i + 1));
    }
}

