    for (int i = 87; i <= 100; i++) {
        iterator.hasNext();
        TimeValuePair timeValuePair = iterator.next();
        assertEquals(i, timeValuePair.getTimestamp());
        assertEquals(i, timeValuePair.getValue().getInt());
    }
    bufferwrite.close();
