@Test
public void testInsert() {
    support.clear();
    assertEquals(true, support.isEmptyOfMemTable());
    OverflowTestUtils.produceInsertData(support);
    assertEquals(false, support.isEmptyOfMemTable());
    int num = 1;
    for (TimeValuePair pair : support.queryOverflowInsertInMemory(deltaObjectId1, measurementId1, dataType1).getSortedTimeValuePairList()) {
        assertEquals(num, pair.getTimestamp());
        assertEquals(num, pair.getValue().getInt());
        num++;
    }
    num = 1;
    for (TimeValuePair pair : support.queryOverflowInsertInMemory(deltaObjectId2, measurementId2, dataType2).getSortedTimeValuePairList()) {
        assertEquals(num, pair.getTimestamp());
        if (num == 2) {
